import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents with .5 rounds to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
});

test('roundCents rounds down', () => {
  assert.equal(roundCents(2.4), 2);
});

test('roundCents rounds up', () => {
  assert.equal(roundCents(2.6), 3);
});

test('roundCents with zero', () => {
  assert.equal(roundCents(0), 0);
});

test('roundCents with negative', () => {
  assert.equal(roundCents(-0.5), 0);
  assert.equal(roundCents(-2.6), -3);
});

test('formatEuros formats euros', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
});

test('formatEuros with single digit cents', () => {
  assert.equal(formatEuros(1005), '€10.05');
});

test('formatEuros with zero', () => {
  assert.equal(formatEuros(0), '€0.00');
});

test('formatEuros with negative', () => {
  assert.equal(formatEuros(-5), '-€0.05');
});

test('parseEuros parses simple amount', () => {
  const result = parseEuros('12');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1200);
});

test('parseEuros parses with decimals', () => {
  const result = parseEuros('12.5');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1250);
});

test('parseEuros parses with thousands separator', () => {
  const result = parseEuros('1,234.56');
  assert.equal(result.ok, true);
  assert.equal(result.value, 123456);
});

test('RATES exports correct exchange rates', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR', () => {
  const result = convert(10000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert EUR to USD', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10850);
});

test('convert EUR to GBP', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 8425);
});

test('convert with rounding', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, roundCents(1.085));
});

test('convert unknown currency returns error', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert with zero amount', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert with negative amount', () => {
  const result = convert(-10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -10850);
});

test('formatMoney EUR', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney USD', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
});

test('formatMoney GBP', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
});

test('formatMoney with zero', () => {
  assert.equal(formatMoney(0, 'USD'), '$0.00');
});

test('formatMoney with negative', () => {
  assert.equal(formatMoney(-5, 'USD'), '-$0.05');
});

test('formatMoney with single digit cents', () => {
  assert.equal(formatMoney(1005, 'GBP'), '£10.05');
});

test('formatMoney thousands separator', () => {
  assert.equal(formatMoney(12345678, 'USD'), '$123,456.78');
});

test('formatMoney unknown currency uses question mark', () => {
  assert.equal(formatMoney(100, 'JPY'), '?1.00');
});

test('convert EUR 100 to USD', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10850);
  assert.equal(formatMoney(result.value, 'USD'), '$108.50');
});

test('convert USD to GBP', () => {
  const resultUsd = convert(10000, 'USD');
  const resultGbp = convert(resultUsd.value, 'GBP');
  assert.equal(resultGbp.ok, true);
  const gbpAmount = roundCents(resultUsd.value * 0.8425);
  assert.equal(resultGbp.value, gbpAmount);
});

test('convert large amount', () => {
  const result = convert(10000000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10850000);
});

test('convert preserves integer type', () => {
  const result = convert(12345, 'USD');
  assert.equal(Number.isInteger(result.value), true);
});

test('formatMoney with EUR preserves euro sign', () => {
  assert.ok(formatMoney(100, 'EUR').includes('€'));
});

test('formatMoney with USD preserves dollar sign', () => {
  assert.ok(formatMoney(100, 'USD').includes('$'));
});

test('formatMoney with GBP preserves pound sign', () => {
  assert.ok(formatMoney(100, 'GBP').includes('£'));
});

test('convert case sensitive for currency', () => {
  const result = convert(10000, 'usd');
  assert.equal(result.ok, false);
});

test('formatMoney case sensitive for currency', () => {
  const result = formatMoney(10000, 'usd');
  assert.ok(result.includes('?'));
});

test('convert multiple currencies consistency', () => {
  const eur = convert(100, 'EUR');
  const usd = convert(100, 'USD');
  const gbp = convert(100, 'GBP');

  assert.ok(usd.value > eur.value);
  assert.ok(gbp.value < eur.value);
});

